#ifndef MEMORY_H
#define MEMORY_H

#include <stddef.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_PERSISTENT_ARENAS 10
#define ALIGNMENT 64

void mem_sys_init();
void* mem_alloc_persist(size_t size, uint8_t arena_id);
void* mem_alloc_temp(size_t size);
void mem_reset_temp();
size_t mem_get_total_usage();
void mem_free_all_persist(uint8_t arena_id);

#endif

#ifndef RUNTIME_H
#define RUNTIME_H

#include <stddef.h>

void rt_init();
void rt_copy(float* dest, float* src, size_t count);
void rt_zero(float* dest, size_t count);
void rt_rand_uniform(float* dest, size_t count, float min, float max);
void rt_rand_normal(float* dest, size_t count, float mean, float stddev);
void rt_print_stats(float* data, size_t count, const char* name);
void rt_sleep_ms(long ms);

#endif

#include "include/memory.h"
#include <stdlib.h>
#include <sys/mman.h>
#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <math.h>

#define BLOCK_SIZE 1073741824

typedef struct Block {
    void* ptr;
    size_t size;
    size_t used;
    struct Block* next;
} Block;

typedef struct Arena {
    Block* head;
    pthread_mutex_t lock;
    size_t total_size;
} Arena;

static Arena persistent_arenas[MAX_PERSISTENT_ARENAS];
static Arena temp_arena;

static void arena_init(Arena* arena) {
    arena->head = NULL;
    pthread_mutex_init(&arena->lock, NULL);
    arena->total_size = 0;
}

static void* sys_alloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("MMAP_ERROR_FATAL");
        exit(1);
    }
    return ptr;
}

static void* arena_alloc(Arena* arena, size_t size) {
    pthread_mutex_lock(&arena->lock);

    size_t aligned = (size + ALIGNMENT - 1) & ~(ALIGNMENT - 1);
    Block* head = arena->head;

    if (head == NULL || head->used + aligned > head->size) {
        size_t alloc_size = (aligned > BLOCK_SIZE) ? aligned : BLOCK_SIZE;
        Block* new_block = (Block*)malloc(sizeof(Block));
        if (!new_block) {
            pthread_mutex_unlock(&arena->lock);
            return NULL;
        }
        new_block->ptr = sys_alloc(alloc_size);
        new_block->size = alloc_size;
        new_block->used = 0;
        new_block->next = head;
        arena->head = new_block;
        arena->total_size += alloc_size;
        head = new_block;
    }

    void* ptr = (char*)head->ptr + head->used;
    head->used += aligned;

    pthread_mutex_unlock(&arena->lock);
    return ptr;
}

static void arena_reset(Arena* arena) {
    pthread_mutex_lock(&arena->lock);
    Block* curr = arena->head;
    while (curr) {
        curr->used = 0;
        curr = curr->next;
    }
    pthread_mutex_unlock(&arena->lock);
}

static void arena_destroy(Arena* arena) {
    pthread_mutex_lock(&arena->lock);
    Block* curr = arena->head;
    while (curr) {
        Block* next = curr->next;
        munmap(curr->ptr, curr->size);
        free(curr);
        curr = next;
    }
    arena->head = NULL;
    arena->total_size = 0;
    pthread_mutex_unlock(&arena->lock);
    pthread_mutex_destroy(&arena->lock);
}

void mem_sys_init() {
    for (uint8_t i = 0; i < MAX_PERSISTENT_ARENAS; ++i) {
        arena_init(&persistent_arenas[i]);
    }
    arena_init(&temp_arena);
}

void* mem_alloc_persist(size_t size, uint8_t arena_id) {
    if (arena_id >= MAX_PERSISTENT_ARENAS) {
        return NULL;
    }
    return arena_alloc(&persistent_arenas[arena_id], size);
}

void* mem_alloc_temp(size_t size) {
    return arena_alloc(&temp_arena, size);
}

void mem_reset_temp() {
    arena_reset(&temp_arena);
}

void mem_free_all_persist(uint8_t arena_id) {
    if (arena_id < MAX_PERSISTENT_ARENAS) {
        arena_destroy(&persistent_arenas[arena_id]);
    }
}

size_t mem_get_total_usage() {
    size_t total = 0;
    for (uint8_t i = 0; i < MAX_PERSISTENT_ARENAS; ++i) {
        pthread_mutex_lock(&persistent_arenas[i].lock);
        total += persistent_arenas[i].total_size;
        pthread_mutex_unlock(&persistent_arenas[i].lock);
    }
    pthread_mutex_lock(&temp_arena.lock);
    total += temp_arena.total_size;
    pthread_mutex_unlock(&temp_arena.lock);
    return total;
}

void mem_persist_serialize(uint8_t arena_id, const char* path) {
    if (arena_id >= MAX_PERSISTENT_ARENAS) return;
    Arena* arena = &persistent_arenas[arena_id];

    pthread_mutex_lock(&arena->lock);
    FILE* f = fopen(path, "wb");
    if (!f) {
        pthread_mutex_unlock(&arena->lock);
        return;
    }

    Block* curr = arena->head;
    int block_count = 0;
    while (curr) {
        block_count++;
        curr = curr->next;
    }
    fwrite(&block_count, sizeof(int), 1, f);

    curr = arena->head;
    while (curr) {
        fwrite(&curr->size, sizeof(size_t), 1, f);
        fwrite(&curr->used, sizeof(size_t), 1, f);
        fwrite(curr->ptr, curr->used, 1, f);
        curr = curr->next;
    }

    fclose(f);
    pthread_mutex_unlock(&arena->lock);
}

void mem_persist_deserialize(uint8_t arena_id, const char* path) {
    if (arena_id >= MAX_PERSISTENT_ARENAS) return;
    Arena* arena = &persistent_arenas[arena_id];

    pthread_mutex_lock(&arena->lock);
    FILE* f = fopen(path, "rb");
    if (!f) {
        pthread_mutex_unlock(&arena->lock);
        return;
    }

    arena_destroy(arena);

    int block_count = 0;
    fread(&block_count, sizeof(int), 1, f);

    for (int i = 0; i < block_count; ++i) {
        size_t size, used;
        fread(&size, sizeof(size_t), 1, f);
        fread(&used, sizeof(size_t), 1, f);

        Block* new_block = (Block*)malloc(sizeof(Block));
        new_block->ptr = sys_alloc(size);
        new_block->size = size;
        new_block->used = used;
        new_block->next = arena->head;
        arena->head = new_block;
        arena->total_size += size;

        fread(new_block->ptr, used, 1, f);
    }

    fclose(f);
    pthread_mutex_unlock(&arena->lock);
}

#include "include/memory.h"
#include "include/runtime.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

void rt_init() {
    mem_sys_init();
    srand((unsigned int)time(NULL) * (unsigned int)pthread_self());
}

void rt_copy(float* dest, float* src, size_t count) {
    if (count > 0) memcpy(dest, src, count * sizeof(float));
}

void rt_zero(float* dest, size_t count) {
    if (count > 0) memset(dest, 0, count * sizeof(float));
}

void rt_rand_uniform(float* dest, size_t count, float min, float max) {
    float range = max - min;
    for (size_t i = 0; i < count; ++i) {
        dest[i] = min + ((float)rand() / (float)RAND_MAX) * range;
    }
}

void rt_rand_normal(float* dest, size_t count, float mean, float stddev) {
    for (size_t i = 0; i < count; i += 2) {
        float u1 = ((float)rand() / (float)RAND_MAX);
        float u2 = ((float)rand() / (float)RAND_MAX);

        float r = sqrt(-2.0f * log(u1 > 1e-6f ? u1 : 1e-6f));
        float theta = 2.0f * M_PI * u2;

        float z0 = r * cos(theta);
        float z1 = r * sin(theta);

        dest[i] = mean + z0 * stddev;
        if (i + 1 < count) {
            dest[i+1] = mean + z1 * stddev;
        }
    }
}

void rt_print_stats(float* data, size_t count, const char* name) {
    float sum = 0.0f;
    float sq_sum = 0.0f;
    float min_val = 1e30f;
    float max_val = -1e30f;

    if (count == 0) {
        printf("STATS %s: Count=0\n", name);
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        float v = data[i];
        sum += v;
        sq_sum += v * v;
        if (v < min_val) min_val = v;
        if (v > max_val) max_val = v;
    }

    float mean = sum / count;
    float variance = (sq_sum / count) - (mean * mean);
    float stddev = sqrt(variance > 0 ? variance : 0);

    printf("STATS %s: Count=%zu Mean=%.5f Std=%.5f Min=%.5f Max=%.5f\n", 
           name, count, mean, stddev, min_val, max_val);
}

void rt_sleep_ms(long ms) {
    struct timespec req = {0};
    req.tv_sec = ms / 1000;
    req.tv_nsec = (ms % 1000) * 1000000L;
    while (nanosleep(&req, &req) == -1)
        continue;
}

void rt_matrix_copy(float* dest, float* src, int rows, int cols, int src_stride, int dest_stride) {
    if (src_stride == cols && dest_stride == cols) {
        memcpy(dest, src, rows * cols * sizeof(float));
    } else {
        for (int i = 0; i < rows; ++i) {
            memcpy(dest + i * dest_stride, src + i * src_stride, cols * sizeof(float));
        }
    }
}

void rt_transpose(float* A, float* B, int rows, int cols) {
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            B[j * rows + i] = A[i * cols + j];
        }
    }
}

float rt_reduce_sum(float* data, size_t count) {
    float sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        sum += data[i];
    }
    return sum;
}

export void vec_add(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] + b[i];
    }
}

export void vec_sub(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] - b[i];
    }
}

export void vec_mul(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] * b[i];
    }
}

export void vec_scale(uniform float a[], uniform float s, uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] * s;
    }
}

export void vec_div(uniform float a[], uniform float b[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = a[i] / b[i];
    }
}

export void vec_inv_sqrt(uniform float a[], uniform float out[], uniform int count, uniform float eps) {
    foreach (i = 0 ... count) {
        out[i] = 1.0f / sqrt(a[i] + eps);
    }
}

export void mat_mul_nn(uniform float A[], uniform float B[], uniform float C[], 
                       uniform int M, uniform int N, uniform int K) {
    foreach (m = 0 ... M, k = 0 ... K) {
        float sum = 0.0f;
        for (uniform int n = 0; n < N; ++n) {
            sum += A[m * N + n] * B[n * K + k];
        }
        C[m * K + k] = sum;
    }
}

export void mat_mul_tn(uniform float A[], uniform float B[], uniform float C[], 
                       uniform int M, uniform int N, uniform int K) {
    foreach (m = 0 ... M, k = 0 ... K) {
        float sum = 0.0f;
        for (uniform int n = 0; n < N; ++n) {
            sum += A[n * M + m] * B[n * K + k];
        }
        C[m * K + k] = sum;
    }
}

export void mat_mul_nt(uniform float A[], uniform float B[], uniform float C[], 
                       uniform int M, uniform int N, uniform int K) {
    foreach (m = 0 ... M, k = 0 ... K) {
        float sum = 0.0f;
        for (uniform int n = 0; n < N; ++n) {
            sum += A[m * N + n] * B[k * N + n];
        }
        C[m * K + k] = sum;
    }
}

export void relu_fwd(uniform float in[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = max(0.0f, in[i]);
    }
}

export void relu_bwd(uniform float grad[], uniform float input[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        out[i] = (input[i] > 0.0f) ? grad[i] : 0.0f;
    }
}

export void gelu_fwd(uniform float in[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        float x = in[i];
        out[i] = 0.5f * x * (1.0f + tanh(0.7978845608f * (x + 0.044715f * x * x * x)));
    }
}

export void gelu_bwd(uniform float grad[], uniform float in[], uniform float out[], uniform int count) {
    foreach (i = 0 ... count) {
        float x = in[i];
        float term1 = 0.5f;
        float term2_arg = 0.7978845608f * (x + 0.044715f * x * x * x);
        float tanh_val = tanh(term2_arg);
        float sech2_val = 1.0f - tanh_val * tanh_val;
        float d_term2_arg = 0.7978845608f * (1.0f + 0.044715f * 3.0f * x * x);
        float d_out = term1 * (1.0f + tanh_val) + term1 * x * sech2_val * d_term2_arg;
        out[i] = grad[i] * d_out;
    }
}

export void softmax_fwd(uniform float in[], uniform float out[], uniform int rows, uniform int cols) {
    foreach (r = 0 ... rows) {
        float max_val = -1e30f;
        for (uniform int c = 0; c < cols; ++c) {
            max_val = max(max_val, in[r * cols + c]);
        }

        float sum = 0.0f;
        for (uniform int c = 0; c < cols; ++c) {
            float exp_v = exp(in[r * cols + c] - max_val);
            out[r * cols + c] = exp_v;
            sum += exp_v;
        }

        float inv_sum = 1.0f / sum;
        for (uniform int c = 0; c < cols; ++c) {
            out[r * cols + c] *= inv_sum;
        }
    }
}

export void layer_norm_fwd(uniform float in[], uniform float gamma[], uniform float beta[], uniform float out[], uniform float cache_mean[], uniform float cache_invstd[], uniform int rows, uniform int cols) {
    foreach (r = 0 ... rows) {
        float sum = 0.0f;
        float sq_sum = 0.0f;
        for (uniform int c = 0; c < cols; ++c) {
            float val = in[r * cols + c];
            sum += val;
            sq_sum += val * val;
        }
        float mean = sum / cols;
        float var = (sq_sum / cols) - (mean * mean);
        float inv_std = 1.0f / sqrt(var + 1e-5f);

        cache_mean[r] = mean;
        cache_invstd[r] = inv_std;

        for (uniform int c = 0; c < cols; ++c) {
            float norm = (in[r * cols + c] - mean) * inv_std;
            out[r * cols + c] = norm * gamma[c] + beta[c];
        }
    }
}

export void layer_norm_bwd_grad_w(uniform float grad_out[], uniform float norm_in[], uniform float grad_w[], uniform int rows, uniform int cols) {
    foreach (c = 0 ... cols) {
        float sum = 0.0f;
        for (uniform int r = 0; r < rows; ++r) {
            sum += grad_out[r * cols + c] * norm_in[r * cols + c];
        }
        grad_w[c] = sum;
    }
}

export void layer_norm_bwd_grad_b(uniform float grad_out[], uniform float grad_b[], uniform int rows, uniform int cols) {
    foreach (c = 0 ... cols) {
        float sum = 0.0f;
        for (uniform int r = 0; r < rows; ++r) {
            sum += grad_out[r * cols + c];
        }
        grad_b[c] = sum;
    }
}

export void layer_norm_bwd_grad_input(uniform float grad_out[], uniform float in[], uniform float gamma[], 
                                      uniform float mean[], uniform float inv_std[], uniform float grad_in[], 
                                      uniform int rows, uniform int cols) {
    foreach (r = 0 ... rows) {
        float inv_n = 1.0f / cols;
        float sum1 = 0.0f;
        float sum2 = 0.0f;
        float m = mean[r];
        float istd = inv_std[r];

        for (uniform int c = 0; c < cols; ++c) {
            float norm = (in[r * cols + c] - m) * istd;
            float g_out = grad_out[r * cols + c];
            sum1 += g_out * gamma[c] * norm;
            sum2 += g_out * gamma[c];
        }

        float term1_scale = istd * sum2;
        float term2_scale = istd * inv_n * sum1;

        for (uniform int c = 0; c < cols; ++c) {
            float norm = (in[r * cols + c] - m) * istd;
            float g_out = grad_out[r * cols + c];

            float derivative_norm = g_out * gamma[c];
            float derivative_mean_term = term1_scale * inv_n;
            float derivative_var_term = term2_scale * norm;

            grad_in[r * cols + c] = (derivative_norm - derivative_mean_term - derivative_var_term) * istd;
        }
    }
}

export void adam_update(uniform float params[], uniform float grads[], 
                        uniform float m[], uniform float v[],
                        uniform float lr, uniform float b1, uniform float b2, 
                        uniform float eps, uniform float t, uniform int count) {
    foreach (i = 0 ... count) {
        float g = grads[i];
        float next_m = b1 * m[i] + (1.0f - b1) * g;
        float next_v = b2 * v[i] + (1.0f - b2) * g * g;

        m[i] = next_m;
        v[i] = next_v;

        float m_hat = next_m / (1.0f - pow(b1, t));
        float v_hat = next_v / (1.0f - pow(b2, t));

        params[i] -= lr * m_hat / (sqrt(v_hat) + eps);
    }
}

