(load "src/carp/ffi.carp")

(deftype Tensor [
    ptr (Ptr Float)
    rows Int
    cols Int
    size Int
])

(defmodule Tensor
    (defn create-persist [r c arena-id]
        (let [sz (* r c)
              bytes (* sz 4)]
            (Tensor.init (mem-alloc-persist (Long.from-int bytes) arena-id) r c sz)))

    (defn create-temp [r c]
        (let [sz (* r c)
              bytes (* sz 4)]
            (Tensor.init (mem-alloc-temp (Long.from-int bytes)) r c sz)))

    (defn rand-normal [r c mean std arena-id]
        (let [t (create-persist r c arena-id)]
            (do
                (rt-rand-normal (Tensor.ptr t) (Long.from-int (Tensor.size t)) mean std)
                t)))

    (defn rand-uniform [r c min max arena-id]
        (let [t (create-persist r c arena-id)]
            (do
                (rt-rand-uniform (Tensor.ptr t) (Long.from-int (Tensor.size t)) min max)
                t)))

    (defn zero-grad [t]
        (rt-zero (Tensor.ptr t) (Long.from-int (Tensor.size t))))

    (defn print-debug [t name]
        (rt-print-stats (Tensor.ptr t) (Long.from-int (Tensor.size t)) (cstr name)))
)

(load "src/carp/tensor.carp")

(deftype AdamState [
    m Tensor
    v Tensor
    t Float
])

(defmodule Adam
    (defn create [params arena-id]
        (let [rows (Tensor.rows params)
              cols (Tensor.cols params)
              m (Tensor.create-persist rows cols arena-id)
              v (Tensor.create-persist rows cols arena-id)]
            (do
                (Tensor.zero-grad m)
                (Tensor.zero-grad v)
                (AdamState.init m v 1.0f))))

    (defn step [state params grads lr]
        (let [m (AdamState.m state)
              v (AdamState.v state)
              t (AdamState.t state)
              sz (Tensor.size params)]
            (do
                (adam-update 
                    (Tensor.ptr params) 
                    (Tensor.ptr grads) 
                    (Tensor.ptr m) 
                    (Tensor.ptr v) 
                    lr 0.9f 0.999f 1e-8f t sz)
                (AdamState.set-t state (+ t 1.0f)))))
)

(load "src/carp/optimizer.carp")

(deftype Linear [
    weights Tensor
    biases Tensor
    grad-w Tensor
    grad-b Tensor
    opt-w AdamState
    opt-b AdamState
    cache-input Tensor
])

(defmodule Linear
    (defn create [in-dim out-dim arena-id]
        (let [w (Tensor.rand-normal in-dim out-dim 0.0f 0.02f arena-id)
              b (Tensor.create-persist 1 out-dim arena-id)
              gw (Tensor.create-persist in-dim out-dim arena-id)
              gb (Tensor.create-persist 1 out-dim arena-id)
              ow (Adam.create w arena-id)
              ob (Adam.create b arena-id)
              cache (Tensor.create-temp 1 1)]
            (do
                (Tensor.zero-grad b)
                (Linear.init w b gw gb ow ob cache))))

    (defn forward [layer input]
        (let [batch (Tensor.rows input)
              in-feat (Tensor.cols input)
              out-feat (Tensor.cols (Linear.weights layer))
              w (Linear.weights layer)
              b (Linear.biases layer)
              out (Tensor.create-temp batch out-feat)]
            (do
                (Linear.set-cache-input layer input)
                (mat-mul_nn (Tensor.ptr input) (Tensor.ptr w) (Tensor.ptr out) batch in-feat out-feat)
                (for [i 0 batch]
                    (let [offset (* i out-feat)]
                        (vec-add 
                            (Pointer.add (Tensor.ptr out) (Long.from-int offset)) 
                            (Tensor.ptr b) 
                            (Pointer.add (Tensor.ptr out) (Long.from-int offset)) 
                            out-feat)))
                out)))

    (defn backward [layer grad-out]
        (let [input (Linear.cache-input layer)
              w (Linear.weights layer)
              gw (Linear.grad-w layer)
              gb (Linear.grad-b layer)
              batch (Tensor.rows grad-out)
              out-feat (Tensor.cols grad-out)
              in-feat (Tensor.cols input)
              grad-input (Tensor.create-temp batch in-feat)]
            (do
                (mat-mul_tn (Tensor.ptr input) (Tensor.ptr grad-out) (Tensor.ptr gw) in-feat batch out-feat)
                (for [i 0 batch]
                    (let [offset (* i out-feat)]
                        (vec-add 
                            (Tensor.ptr gb) 
                            (Pointer.add (Tensor.ptr grad-out) (Long.from-int offset)) 
                            (Tensor.ptr gb) 
                            out-feat)))
                (mat-mul_nt (Tensor.ptr grad-out) (Tensor.ptr w) (Tensor.ptr grad-input) batch out-feat in-feat)
                grad-input)))

    (defn update [layer lr]
        (do
            (Adam.step (Linear.opt-w layer) (Linear.weights layer) (Linear.grad-w layer) lr)
            (Adam.step (Linear.opt-b layer) (Linear.biases layer) (Linear.grad-b layer) lr)
            (Tensor.zero-grad (Linear.grad-w layer))
            (Tensor.zero-grad (Linear.grad-b layer))))
)

(load "src/carp/layer.carp")

(deftype AttentionHead [
    q-proj Linear
    k-proj Linear
    v-proj Linear
    output-proj Linear
    cache-qk Tensor
    cache-v Tensor
])

(defmodule AttentionHead
    (defn create [in-dim head-dim arena-id]
        (AttentionHead.init
            (Linear.create in-dim head-dim arena-id)
            (Linear.create in-dim head-dim arena-id)
            (Linear.create in-dim head-dim arena-id)
            (Linear.create head-dim in-dim arena-id)
            (Tensor.create-temp 1 1) 
            (Tensor.create-temp 1 1)))

    (defn forward [head input]
        (let [batch (Tensor.rows input)
              q (Linear.forward (AttentionHead.q-proj head) input)
              k (Linear.forward (AttentionHead.k-proj head) input)
              v (Linear.forward (AttentionHead.v-proj head) input)
              dim-k (Tensor.cols q)
              scale (1.0f / (Double.sqrt (Float.from-int dim-k)))
              qk-score (Tensor.create-temp batch batch)
              weights (Tensor.create-temp batch batch)
              out (Tensor.create-temp batch dim-k)]
            (do
                (mat-mul_nt (Tensor.ptr q) (Tensor.ptr k) (Tensor.ptr qk-score) batch dim-k batch)
                (vec-scale (Tensor.ptr qk-score) scale (Tensor.ptr qk-score) (Tensor.size qk-score))

                (softmax-fwd (Tensor.ptr qk-score) (Tensor.ptr weights) batch batch)
                (AttentionHead.set-cache-qk head weights)

                (mat-mul_nn (Tensor.ptr weights) (Tensor.ptr v) (Tensor.ptr out) batch batch dim-k)
                (AttentionHead.set-cache-v head v)

                (Linear.forward (AttentionHead.output-proj head) out))))
)

(load "src/carp/layer.carp")
(load "src/carp/attention.carp")

(deftype TransformerBlock [
    norm1 LayerNorm
    attn AttentionHead
    norm2 LayerNorm
    ffn1 Linear
    ffn2 Linear
])

(deftype LayerNorm [
    gamma Tensor
    beta Tensor
    grad-g Tensor
    grad-b Tensor
    cache-mean Tensor
    cache-invstd Tensor
])

(defmodule LayerNorm
    (defn create [dim arena-id]
        (let [g (Tensor.create-persist 1 dim arena-id)
              b (Tensor.create-persist 1 dim arena-id)
              gg (Tensor.create-persist 1 dim arena-id)
              gb (Tensor.create-persist 1 dim arena-id)
              cm (Tensor.create-temp 1 dim)
              ci (Tensor.create-temp 1 dim)]
            (do
                (Tensor.rand-uniform g 1 dim 1.0f 1.0f) 
                (Tensor.zero-grad b)
                (LayerNorm.init g b gg gb cm ci))))

    (defn forward [ln input]
        (let [batch (Tensor.rows input)
              dim (Tensor.cols input)
              out (Tensor.create-temp batch dim)]
            (do
                (layer-norm-fwd (Tensor.ptr input) (Tensor.ptr (LayerNorm.gamma ln)) (Tensor.ptr (LayerNorm.beta ln))
                                (Tensor.ptr out) (Tensor.ptr (LayerNorm.cache-mean ln)) (Tensor.ptr (LayerNorm.cache-invstd ln)) 
                                batch dim)
                out)))
)

(defmodule TransformerBlock
    (defn create [dim heads arena-id]
        (let [attn (AttentionHead.create dim (Int.div dim heads) arena-id)
              n1 (LayerNorm.create dim arena-id)
              n2 (LayerNorm.create dim arena-id)
              f1 (Linear.create dim (* dim 4) arena-id)
              f2 (Linear.create (* dim 4) dim arena-id)]
            (TransformerBlock.init n1 attn n2 f1 f2)))

    (defn forward [block input]
        (let [norm-in (LayerNorm.forward (TransformerBlock.norm1 block) input)
              attn-out (AttentionHead.forward (TransformerBlock.attn block) norm-in)
              res1-temp (Tensor.create-temp (Tensor.rows input) (Tensor.cols input))]
            (do
                (vec-add (Tensor.ptr input) (Tensor.ptr attn-out) (Tensor.ptr res1-temp) (Tensor.size input))
                (let [norm2-in (LayerNorm.forward (TransformerBlock.norm2 block) res1-temp)
                      ffn1-out (Linear.forward (TransformerBlock.ffn1 block) norm2-in)
                      act-out (Tensor.create-temp (Tensor.rows ffn1-out) (Tensor.cols ffn1-out))]
                    (do
                        (gelu-fwd (Tensor.ptr ffn1-out) (Tensor.ptr act-out) (Tensor.size ffn1-out))
                        (let [ffn2-out (Linear.forward (TransformerBlock.ffn2 block) act-out)
                              final-out (Tensor.create-temp (Tensor.rows ffn2-out) (Tensor.cols ffn2-out))]
                            (do
                                (vec-add (Tensor.ptr res1-temp) (Tensor.ptr ffn2-out) (Tensor.ptr final-out) (Tensor.size final-out))
                                final-out)))))))
)

(load "src/carp/transformer.carp")

(deftype AGIModel [
    input-layer Linear
    block1 TransformerBlock
    block2 TransformerBlock
    output-layer Linear
])

(defmodule AGIModel
    (defn create [dim blocks heads arena-id]
        (AGIModel.init
            (Linear.create 1 dim arena-id)
            (TransformerBlock.create dim heads arena-id)
            (TransformerBlock.create dim heads arena-id)
            (Linear.create dim 10 arena-id)))

    (defn forward [model input]
        (let [h0 (Linear.forward (AGIModel.input-layer model) input)
              h1 (TransformerBlock.forward (AGIModel.block1 model) h0)
              h2 (TransformerBlock.forward (AGIModel.block2 model) h1)
              out (Linear.forward (AGIModel.output-layer model) h2)
              final-out (Tensor.create-temp (Tensor.rows out) (Tensor.cols out))]
            (do
                (softmax-fwd (Tensor.ptr out) (Tensor.ptr final-out) (Tensor.rows out) (Tensor.cols out))
                final-out)))

    (defn update [model lr]
        (do
            (Linear.update (AGIModel.input-layer model) lr)
            (Linear.update (AGIModel.output-layer model) lr)
            ))
)

(load "src/carp/agi.carp")

(defn main []
    (do
        (rt-init)
        (println "AGI_SYSTEM_BOOT_SEQUENCE_INITIATED")

        (let [batch-size 32
              seq-len 16
              dim 256
              blocks 2
              heads 8
              arena-model 10
              arena-data 11
              epochs 1000
              lr 0.0001f]

            (let [model (AGIModel.create dim blocks heads arena-model)
                  inputs (Tensor.rand-normal batch-size dim 0.0f 1.0f arena-data)
                  targets (Tensor.rand-uniform batch-size 10 0.0f 1.0f arena-data)

                  loss-val (Tensor.create-persist 1 1 arena-model)
                  grad-loss (Tensor.create-persist batch-size 10 arena-model)]

                (println "AGI_MODEL_LOADING_COMPLETE")

                (for [i 0 epochs]
                    (do
                        (let [preds (AGIModel.forward model inputs)]
                            (do
                                (mse-loss (Tensor.ptr preds) (Tensor.ptr targets) (Tensor.ptr grad-loss) (Tensor.ptr loss-val) (Tensor.size preds))

                                (if (= (mod i 50) 0)
                                    (Tensor.print-debug loss-val (String.concat ["EPOCH_" (String.from-int i) "_LOSS"]))
                                    ())

                                (AGIModel.update model lr) 
                            ))
                        (mem-reset-temp)
                        (if (= (mod i 500) 0) (rt-sleep_ms 10) ())
                    )
                )

                (println "AGI_TRAINING_CYCLE_TERMINATED")
                (mem-free-all_persist arena-model)
                (mem-free-all_persist arena-data)
            )
    )))
